query($search: String!) {
  search(type: ISSUE, query: $search, first: 100) {    edges {
      node {
        ... on PullRequest {
          id
          title
          url
          isDraft
          reviewRequests(first: 100) {
            nodes {
              requestedReviewer {
                ... on User {
                  login
                }
                ... on Team {
                  name
                }
                ... on Mannequin {
                  login
                }
              }
            }
          }
          repository {
            url
            name
            owner {
              login
            }
          }
          reviewDecision
          updatedAt
          author {
            login
          }
          additions
          deletions
          headRefOid
          comments(last: 5) {
            edges {
              node {
                updatedAt
                author {
                  login
                }
                url
              }
            }
          }
          commits(last: 1) {
            nodes {
              commit {
                author {
                  date
                  email
                  name
                }
                # scalar only - see StatusCheckRollup in the struct above
                statusCheckRollup {
                  state
                }
              }
            }
          }
          # threads can't be filtered on isResolved server-side, so every
          # thread is fetched: this first page here, the rest per PR through
          # queryReviewThreadsPage (see fetchRemainingReviewThreads). The
          # page is kept small because its cost multiplies with the 100 PRs
          # above; a follow-up query only costs what that one PR has.
          reviewThreads(first: 15) {
            totalCount
            pageInfo {
              hasNextPage
              endCursor
            }
            edges {
              node {
                isResolved
                isOutdated
                isCollapsed
                firstComment: comments(first: 1) {
                  nodes {
                    author {
                      login
                    }
                  }
                }
                lastComment: comments(last: 1) {
                  nodes {
                    author {
                      login
                    }
                    url
                    createdAt
                    reactions(first: 7) {
                        edges {
                            node {
                                content
                                user {
                                    login
                                }
                            }
                        }
                    }
                  }
                }
              }
            }
          }
          reviews(first: 20) {
            edges {
                node {
                    author {
                        login
                    }
                    url
                    state
                    submittedAt
                }
            }
          }
        }
      }
    }
  }
}

